'use strict';
let situationalData,researchNotes;
function researchLinks(sources){return sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.label)} ↗</a>`).join(' · ')}
function injuryWatch(teamId,notes=researchNotes){const reports=notes.injuries.filter(r=>r.team===teamId);return reports.length?reports.map(r=>`<div class="signal"><span class="tag">${esc(r.position)} · REPORT ${esc(r.reportDate)}</span><h3>${esc(r.player)}</h3><b>${esc(r.status)}</b><p>${esc(r.text)}</p><p class="tiny">${researchLinks(r.sources)}</p></div>`).join(''):'<p>No verified injury entry loaded for this team. Center, OL and DL availability are <b>unknown</b>, not confirmed healthy.</p>'}
function renderSituationalMatch(f){
 if(!situationalData||!researchNotes)return;
 const target=$('situationalMatch');if(!target)return;const g=game(f),a=situationalData.units[g.away],h=situationalData.units[g.home];
 const rate=(x,k,den)=>x&&x[den]?`${(100*x[k]/x[den]).toFixed(1)}% (${x[k]}/${x[den]})`:'Not enough classified plays';
 const lineSide=(team,other,id,oid)=>`<div class="patterncard"><h3>${esc(name(id))} offense vs ${esc(name(oid))} defense</h3><div class="tablewrap"><table><tr><th>What happens at the line?</th><th>Offense</th><th>Opposing defense</th></tr><tr><td>Sacks allowed / generated per classified pass play</td><td>${rate(team?.offense,'sacks','passPlays')}</td><td>${rate(other?.defense,'sacks','passPlays')}</td></tr><tr><td>Runs stopped for no gain or a loss</td><td>${rate(team?.offense,'stuffed','runs')}</td><td>${rate(other?.defense,'stuffed','runs')}</td></tr><tr><td>Short-yardage runs converted / allowed</td><td>${rate(team?.offense,'shortConverted','shortRuns')}</td><td>${rate(other?.defense,'shortConverted','shortRuns')}</td></tr></table></div><p class="tiny">Offense: ${team?.offense.games||0} games; opposing defense: ${other?.defense.games||0} games. These are unadjusted team outcomes, not individual lineman grades.</p><details class="technical" ${researchNotes.injuries.some(r=>r.team===id)?'open':''}><summary>Injury and center watch · ${esc(name(id))}</summary>${injuryWatch(id)}</details></div>`;
 const live=situationalData.matchups[g.id],groups=live?situationalData.cohorts.filter(r=>live.conditions[r.key]===true):[];
 target.innerHTML=`<div class="eyebrow">THE LINE OF SCRIMMAGE</div><h2>Protection, rushing and center availability</h2>${lineSide(a,h,g.away,g.home)}${lineSide(h,a,g.home,g.away)}<p class="tiny">A high offensive sack or stopped-run rate suggests a problem to investigate; a high opposing defensive rate suggests disruption. QB decisions, running backs, scheme and opponent quality also affect these numbers. Pressure without a sack is not measured. No automatic score adjustment is applied.</p><details class="technical"><summary>Definitions and missing line data</summary><p>${esc(situationalData.notes)}</p><p>${esc(researchNotes.coverage)}</p><h4>Play-by-play source games</h4>${[g.away,g.home].map(id=>`<p><b>${esc(name(id))}:</b> ${researchLinks((situationalData.units[id]?.sources||[]).map((url,i)=>({url,label:`Game ${i+1}`})))}</p>`).join('')}<p>Research hypothesis: a replacement center, an inexperienced quarterback and a disruptive defensive front may compound communication and protection risks. We have not measured that interaction or assigned it a point value.</p></details><h3>Historical situations matching this game</h3>${groups.length?groups.map(r=>`<div class="contextrow"><b>${esc(r.label)}</b><p>Underdogs went ${r.wins}–${r.losses} in ${r.n} matching games in our test. ${r.unknown} games lacked enough information to classify this condition. This is descriptive context, not a replacement win probability.</p></div>`).join(''):live?'<p>No positive match among the six tested conditions. That does not mean there are no other situational factors.</p>':'<p>A posted market underdog is needed to match these situations.</p>'}<p class="tiny">Matchup history is not the same as verified rivalry intensity. Coach matchups, travel miles, crowd levels and current-game center availability are not comprehensively connected. Play data through ${esc(situationalData.asOf)}; injury entries have their own report dates.</p>`;
}
function renderResearchFindings(s,n){return `<article id="situationalResearch"><div class="eyebrow">RESEARCH DESK</div><h2>Rivalries, coaching, travel and the trenches</h2><p>What the evidence supports, what we can test, and what is still missing. Research findings do not automatically change the forecast.</p>${n.findings.map(r=>`<details class="technical"><summary>${esc(r.title)}</summary><span class="tag">${esc(r.status)}</span><p>${esc(r.finding)}</p><p><b>How to test it:</b> ${esc(r.test)}</p><a href="${esc(r.source)}" target="_blank" rel="noreferrer">${esc(r.sourceLabel)} ↗</a></details>`).join('')}<h3>Center and defensive-line evidence</h3>${[...new Set(n.injuries.map(r=>r.team))].map(id=>`<h4>${esc(name(id))}</h4>${injuryWatch(id,n)}`).join('')}<p>${esc(n.coverage)}</p><h3>What we tested in our own data</h3><p>Six fixed conditions across the same ${s.rows.length} historical test games. Records below belong to the <b>sportsbook underdog</b>, even when the condition describes the favorite.</p><div class="tablewrap"><table><tr><th>Condition</th><th>Underdog record</th><th>Model expected</th><th>Condition absent</th><th>Unknown</th></tr>${s.cohorts.map(r=>`<tr><td>${esc(r.label)}</td><td>${r.wins}–${r.losses} (${r.n} games)</td><td>${r.expected.toFixed(1)} wins</td><td>${r.comparison.wins}–${r.comparison.losses}</td><td>${r.unknown}</td></tr>`).join('')}</table></div><p class="tiny">Comparison groups are not matched for team strength or spread. They cannot isolate a causal effect. Groups overlap; unknown cases are excluded rather than treated as false. Previous-meeting rules use a three-season limit; three-win series streaks require all three meetings within five seasons. Road streaks mean consecutive team games, not proof of continuous travel. All rules use information from earlier dates. This short, already-inspected sample is exploratory.</p><details class="technical"><summary>See the games behind each condition</summary>${s.cohorts.map(r=>`<h3>${esc(r.label)} · ${r.wins}–${r.losses}</h3><div class="cohortgames">${r.ids.map(id=>{const x=s.rows.find(x=>x.id===id);return `<a href="${esc(x.url)}" target="_blank" rel="noreferrer"><span>${esc(name(x.team))} vs ${esc(name(x.opponent))}<small>${esc(x.date.slice(0,10))} UTC date · ${pct(x.p)} model chance</small></span><b>${x.won?'WON':'LOST'}</b></a>`}).join('')}</div>`).join('')}</details><h3>Next data priorities</h3><ol>${n.priorities.map(p=>`<li>${esc(p)}</li>`).join('')}</ol><p class="tiny"><a href="situational-research.json" download>Download situation results and line indicators</a> · <a href="research-notes.json" download>Download research sources and injury evidence</a></p></article>`}
async function loadSituationalResearch(){try{[situationalData,researchNotes]=await Promise.all(['situational-research.json','research-notes.json'].map(async path=>{const r=await fetch(path);if(!r.ok)throw Error(path);return r.json()}));await initialDataReady;$('method').insertAdjacentHTML('afterbegin',renderResearchFindings(situationalData,researchNotes));$('lab').insertAdjacentHTML('beforeend','<article id="situationalMatch"></article>');if(current)renderSituationalMatch(current)}catch(error){console.error(error)}}
let D,M,H,A,B,P,U,current,matchupBriefEngine,historyFilter="all";const $=id=>document.getElementById(id);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=(x,n=1)=>Number(x).toFixed(n),pct=x=>`${Math.round(100*x)}%`,sg=x=>(x>0?'+':'')+fmt(x);const name=t=>D.teams[t]?.name||t;
function cdf(x){let z=Math.abs(x),t=1/(1+.2316419*z),v=1-.3989422804*Math.exp(-z*z/2)*t*(.319381530+t*(-.356563782+t*(1.781477937+t*(-1.821255978+t*1.330274429))));return x>=0?v:1-v}
function forecast(f){const margin=f.coreMargin,total=Math.max(Math.abs(margin)+2,f.coreTotal),p=cdf(margin/f.coreSd);let h=Math.round((total+margin)/2),a=Math.round((total-margin)/2);const adjusted=h===a;if(adjusted){if(margin>=0)h++;else a++;}return {margin,total,h,a,adjusted,p,upset:Math.min(p,1-p),blow:cdf((-21-margin)/f.coreSd)+1-cdf((21-margin)/f.coreSd)}}
const conferenceNames={'Southeastern Conference':'SEC','Atlantic Coast Conference':'ACC','Big Ten Conference':'Big Ten','Big 12 Conference':'Big 12','Pac-12 Conference':'Pac-12','American Conference':'American','Conference USA':'CUSA','Mid-American Conference':'MAC','Mountain West Conference':'Mountain West','Sun Belt Conference':'Sun Belt','FBS Independents':'Independents','Cross-conference':'Cross-conference'};
const confOrder=Object.keys(conferenceNames);const shortConf=c=>conferenceNames[c]||c;
function logo(t){const team=D.teams[t],url=A?.logos.includes(t)?`assets/logos/${encodeURIComponent(t)}.png`:team?.logo;return url?`<img class="teamlogo" src="${esc(url)}" alt="${esc(name(t))} logo" loading="lazy" onerror="this.style.visibility='hidden'">`:''}
function groupOf(g){const h=D.teams[g.home].conference,a=D.teams[g.away].conference;return h===a?h:'Cross-conference'}
function venueKey(v){return String(v||'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function sameVenue(a,b){if(a.venueId&&b.venueId)return a.venueId===b.venueId;const x=venueKey(a.venue),y=venueKey(b.venue);if(!x||!y||x.includes('unavailable')||y.includes('tba'))return false;return x===y||(['jordanhare','sanfordstadium','bryantdenny','tigerstadium','benhillgriffin','neyland','doakcampbell','davidbooth','memorialstadium'].filter(k=>k!=='memorialstadium').some(k=>x.includes(k)&&y.includes(k)))}
function meetings(g){return H.games.filter(z=>z.date<g.date&&((z.home===g.home&&z.away===g.away)||(z.home===g.away&&z.away===g.home))).sort((a,b)=>b.date.localeCompare(a.date))}
function historyReport(targetGame=null,prefix='history',filter=historyFilter){const g=targetGame||game(current),rows=meetings(g),at=rows.filter(z=>sameVenue(z,g)),wins=rows.filter(z=>(z.home===g.home?z.hs-z.as:z.as-z.hs)>0).length;const streak=(()=>{if(!rows.length)return '—';const winner=z=>z.hs>z.as?z.home:z.away;let n=0;for(const r of rows){if(winner(r)!==winner(rows[0]))break;n++}return `${name(winner(rows[0]))} · ${n}`})();
 $(prefix+'Summary').innerHTML=`<div class="seriesstats"><div><small>SERIES SINCE 2016</small><b>${rows.length?`${wins}–${rows.length-wins}`:'—'}</b><span>${esc(name(g.home))} record</span></div><div><small>${g.venue==='All venues'?'STADIUMS IN SERIES':'AT THIS STADIUM'}</small><b>${g.venue==='All venues'?new Set(rows.map(r=>r.venue)).size:at.length?`${at.filter(z=>(z.home===g.home?z.hs-z.as:z.as-z.hs)>0).length}–${at.filter(z=>(z.home===g.home?z.hs-z.as:z.as-z.hs)<0).length}`:'—'}</b><span>${g.venue==='All venues'?'Select a stadium to filter':esc(name(g.home))+' · '+at.length+' meetings'}</span></div><div><small>CURRENT LOADED STREAK</small><b class="streak">${esc(streak)}</b><span>through ${D.asOf}</span></div></div>`;
 const selected=filter==='venue'?at:rows;$(prefix+'Table').innerHTML=selected.length?`<table class="seriesTable"><tr><th>Season / date</th><th>Matchup & final</th><th>Stadium</th><th>Winner</th></tr>${selected.map(z=>`<tr><td><b>${z.season}</b><small>${esc(z.date.slice(0,10))}</small></td><td><div class="historyteam">${logo(z.away)}<span>${esc(name(z.away))}</span><b>${z.as}</b></div><div class="historyteam">${logo(z.home)}<span>${esc(name(z.home))}</span><b>${z.hs}</b></div></td><td>${esc(z.venue)}${z.neutral?' · Neutral':''}</td><td><a href="${esc(z.url)}" target="_blank" rel="noreferrer">${esc(name(z.hs>z.as?z.home:z.away))} ↗</a></td></tr>`).join('')}</table>`:`<div class="empty">No ${filter==='venue'?'head-to-head games at this stadium':'meetings'} found in the loaded 2016–2026 regular-season schedules. This does not mean these teams have never played.</div>`;
 const failures=H.failures.filter(x=>[g.home,g.away].includes(x[0]));$(prefix+'Note').textContent=`Source: ESPN schedule results, 2016–2026 through October 20. ${failures.length?`${failures.length} team-season requests missing for this pair.`:'All requested team-season schedules for this pair loaded.'} Postseason completeness is not guaranteed. Records are descriptive; old results do not automatically alter today’s forecast.`;if(prefix==='history')document.querySelectorAll('[data-history]').forEach(b=>b.classList.toggle('active',b.dataset.history===historyFilter));}
function matchupFacts(g){const rows=meetings(g),out=[];const winner=r=>r.hs>r.as?r.home:r.away,add=(kind,title,text,sourceRows,priority=0)=>out.push({kind,title,text,scope:'Loaded regular-season results · 2016–2026',sources:sourceRows.slice(0,5).map(r=>({label:r.date.slice(0,10)+' result',url:r.url})),priority});if(rows.length){
 const w=winner(rows[0]);let streak=0;for(const r of rows){if(winner(r)!==w)break;streak++}if(streak>=2)add('Winning streak',`${name(w)} has won ${streak} straight loaded meetings`,`${name(w===g.home?g.away:g.home)} has not won any of the ${streak} most recent meetings in this dataset. The latest was ${rows[0].hs}–${rows[0].as} on ${rows[0].date.slice(0,10)}.`,rows.slice(0,streak),80+streak);
 for(const t of [g.home,g.away]){const win=rows.find(r=>winner(r)===t);if(win&&win!==rows[0]){const since=rows.filter(r=>r.date>win.date).length;if(since>=2)add('Last series win',`${name(t)}’s last loaded win was in ${win.season}`,`${name(t)} won ${win.home===t?win.hs:win.as}–${win.home===t?win.as:win.hs} on ${win.date.slice(0,10)}. There have been ${since} loaded meetings since that win.`,[win,...rows.slice(0,2)],75+since)}}
 const venue=rows.filter(r=>sameVenue(r,g));if(venue.length>=2){const wins=venue.filter(r=>winner(r)===g.away).length;if(wins===0||wins===venue.length)add('Stadium quirk',`${name(g.away)} is ${wins}–${venue.length-wins} here in loaded meetings`,`${venue.length} visits to ${g.venue} appear in the 2016–2026 sample. This is a venue-specific series record, not an all-time claim.`,venue,70)}
 const close=rows.slice(0,5).filter(r=>Math.abs(r.hs-r.as)<=8);if(close.length>=3)add('Close-game habit',`${close.length} of the last ${Math.min(rows.length,5)} meetings were one-score games`, 'Each finished within eight points. A recurring close finish is an interesting series pattern, not evidence that today’s teams are evenly matched.',close,65);
 const big=[...rows].sort((a,b)=>Math.abs(b.hs-b.as)-Math.abs(a.hs-a.as))[0];if(Math.abs(big.hs-big.as)>=28)add('Series outlier',`${name(winner(big))} once won this matchup by ${Math.abs(big.hs-big.as)}`,`${big.season}: ${name(big.home)} ${big.hs}, ${name(big.away)} ${big.as}. This is the largest margin in the loaded series window.`,[big],55);
 const last=rows[0],years=Number(g.date.slice(0,4))-last.season;if(years>=3)add('Long-awaited rematch',`Their last loaded meeting was ${years} seasons ago`,`${name(last.home)} hosted ${name(last.away)} on ${last.date.slice(0,10)}. The final was ${last.hs}–${last.as}.`,[last],60);
 const swing=rows.slice(0,2);if(swing.length===2){const a=swing[0].home===g.home?swing[0].hs-swing[0].as:swing[0].as-swing[0].hs,b=swing[1].home===g.home?swing[1].hs-swing[1].as:swing[1].as-swing[1].hs;if(a*b<0&&Math.abs(a-b)>=30)add('Wild reversal',`A ${Math.abs(a-b)}-point swing between the last two meetings`,`${name(g.home)} went from a ${Math.abs(b)}-point ${b>0?'win':'loss'} in ${swing[1].season} to a ${Math.abs(a)}-point ${a>0?'win':'loss'} in ${swing[0].season}.`,swing,60)}
}
const pair=[g.home,g.away];if(pair.includes('228')&&pair.includes('259')){out.push({kind:'Verified coach record',title:'Dabo Swinney is 6–0 against Virginia Tech',text:'Clemson’s official 2026 schedule notes report six wins in six meetings under Swinney, including two wins in 2011. This is a verified coaching record, not an extra forecast adjustment.',scope:'Official Clemson notes · entering October 24, 2026',sources:[{label:'Clemson official schedule notes',url:'https://clemsontigers.com/news/2026/01/26/clemson-announces-2026-football-schedule'}],priority:110});out.push({kind:'Rare road trip',title:'Virginia Tech’s first trip to Clemson since 2012',text:'The schools have met elsewhere since then, but Clemson’s official notes identify this as the Hokies’ first return to Memorial Stadium since 2012.',scope:'Official Clemson notes · 2026 matchup',sources:[{label:'Clemson official schedule notes',url:'https://clemsontigers.com/news/2026/01/26/clemson-announces-2026-football-schedule'}],priority:105})}
return [...out,...(P?.games[g.id]||P?.games[M.forecasts.find(f=>{const z=game(f);return [z.home,z.away].includes(g.home)&&[z.home,z.away].includes(g.away)})?.id]||[])].sort((a,b)=>b.priority-a.priority).slice(0,6)}
function factCards(g){const facts=matchupFacts(g);return facts.length?facts.map((f,i)=>`<div class="factcard"><div class="factnumber">${String(i+1).padStart(2,'0')}</div><div><div class="eyebrow">${esc(f.kind)}</div><h3>${esc(f.title)}</h3><p>${esc(f.text)}</p><small>${esc(f.scope)}</small><div class="factsources">${f.sources.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noreferrer">${esc(r.label)} ↗</a>`).join('')}</div></div></div>`).join(''):'<div class="empty">No sufficiently supported oddity found for this matchup in the loaded data. Coach and player trivia is shown only where verified.</div>'}
function archiveGame(){const home=$('historyA').value,away=$('historyB').value;return {id:'archive',home,away,date:D.asOf+'T23:59:59Z',venue:$('archiveVenue').value||'All venues'}}
function refreshArchive(resetVenue=false){if($('historyA').value===$('historyB').value){$('archiveSummary').innerHTML='<div class="empty">Choose two different teams.</div>';$('archiveTable').innerHTML='';$('archiveNote').textContent='';$('archiveFacts').innerHTML='';return}let g=archiveGame();const rows=meetings(g);if(resetVenue){const venues=[...new Set(rows.map(r=>r.venue))].sort();$('archiveVenue').innerHTML='<option value="">All stadiums</option>'+venues.map(v=>`<option>${esc(v)}</option>`).join('');$('archiveVenue').value='';g=archiveGame()}historyReport(g,'archive',$('archiveVenue').value?'venue':'all');$('archiveFacts').innerHTML=factCards(g)}
function openArchive(f){const g=game(f);$('historyA').value=g.home;$('historyB').value=g.away;refreshArchive(true);tab('archive');window.scrollTo({top:200,behavior:'smooth'})}
function fillGames(){const c=$('matchConference').value||'all',fs=M.forecasts.filter(f=>c==='all'||[D.teams[game(f).home].conference,D.teams[game(f).away].conference].includes(c));let groups={};for(const f of fs){const g=game(f),key=c==='all'?groupOf(g):c;(groups[key]??=[]).push(f)}$('game').innerHTML=Object.entries(groups).sort((a,b)=>confOrder.indexOf(a[0])-confOrder.indexOf(b[0])).map(([c,fs])=>`<optgroup label="${esc(shortConf(c))}">${fs.sort((a,b)=>game(a).date.localeCompare(game(b).date)).map(f=>{const g=game(f);return `<option value="${esc(f.id)}">${esc(name(g.away))} at ${esc(name(g.home))} · ${esc(date(g))}</option>`}).join('')}</optgroup>`).join('');return fs}

function game(f){return D.games.find(g=>g.id===f.id)}
function meta(g){return B?.games[g.id]||{channels:[],homeSpread:null}}
function date(g){const m=meta(g),value=m.date||g.date,valid=m.timeValid??g.timeValid;return new Date(value).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',...(valid?{hour:'numeric',minute:'2-digit'}:{})})+(valid?' ET':' · Time TBA')}
function channel(g){const m=meta(g);return m.channels?.length?m.channels.join(' / '):'TV / streaming TBA'}
function line(g){const m=meta(g);if(m.homeSpread===null||m.homeSpread===undefined)return 'Spread not posted';if(m.homeSpread===0)return 'Pick’em';return `${name(m.homeSpread<0?g.home:g.away)} −${fmt(Math.abs(m.homeSpread),1)}`}
function modelLine(f){const g=game(f),q=forecast(f);return Math.abs(q.margin)<.05?'Pick’em':`${name(q.margin>0?g.home:g.away)} −${fmt(Math.abs(q.margin),1)}`}
function upsetInfo(f){const g=game(f),q=forecast(f),m=meta(g),posted=Number.isFinite(m.homeSpread),pickem=posted&&m.homeSpread===0;const home=posted&&!pickem?m.homeSpread>0:q.margin<0;const p=home?q.p:1-q.p;return {p:!posted||pickem?null:p,home,team:home?g.home:g.away,favorite:home?g.away:g.home,market:posted&&!pickem,pickem,label:!posted?'No posted line · upset chance unavailable':pickem?'Pick’em · no underdog':p>.5?'Model favors the upset':p>=.35?'Elevated upset risk':p>=.2?'Live upset possibility':'Lower upset risk',basis:posted?'Sportsbook underdog · outright win':'No market underdog established'}}
function meter(f,compact=false){const u=upsetInfo(f),p=u.p;return `<div class="upsetmeter ${compact?'compact':''}"><div class="meterheading"><span>${compact?esc(name(u.team))+' win chance':'UPSET METER'}</span><b>${p===null?'—':pct(p)}</b></div><div class="metertrack" role="meter" aria-label="${esc(u.pickem?'No market underdog':name(u.team)+' modeled win probability')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p===null?0:Math.round(p*100)}"><i style="width:${p===null?0:Math.round(p*100)}%"></i></div>${compact?'':`<div class="meterticks"><span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100%</span></div><b class="meterlabel">${esc(u.label)}</b><p>${!u.market?'No sportsbook underdog is established. Upset probability is unavailable.':`${esc(name(u.team))} · ${esc(u.basis)}. The meter is the model’s win probability, not a confidence grade.`}</p>`}</div>`}

function evidence(f){if(!upsetInfo(f).market)return {items:[{tag:'NO MARKET UNDERDOG',title:'No upset classification',text:'An upset means the sportsbook underdog wins outright. A missing spread or pick’em cannot establish an underdog.'}],count:0,label:'No upset classification',under:'Neither team',fav:'Neither team'};const g=game(f),q=forecast(f),ui=upsetInfo(f),underHome=ui.home,u=underHome?f.homeProfile:f.awayProfile,v=underHome?f.awayProfile:f.homeProfile,un=name(underHome?g.home:g.away),fav=name(underHome?g.away:g.home);let out=[];let families=new Set();
 if(ui.p!==null&&ui.p>=.3){families.add('baseline');out.push({tag:'COMPETITIVE BASELINE',title:`${un} is within striking distance`,text:`The core model gives ${un} a ${pct(ui.p)} win probability. The model projects it to ${((underHome?q.margin:-q.margin)>0)?'win':'lose'} by ${fmt(Math.abs(q.margin))} points. ${ui.market?'It is the market underdog.':'No market line is available, so this uses the model underdog.'}`})}
 if(u.plays>=80&&v.plays>=80&&u.net>v.net){families.add('efficiency');out.push({tag:'MEASURED EFFICIENCY',title:`The underdog owns the net success-rate edge`,text:`${un}: ${sg(u.net*100)} percentage points; ${fav}: ${sg(v.net*100)}. That is a repeatability signal, though these rates are not individually opponent-adjusted.`})}
 else if(u.plays>=80&&v.plays>=80&&u.exp>v.exp+.015){families.add('efficiency');out.push({tag:'EXPLOSIVE PLAY PATH',title:`${un} has a big-play route to an upset`,text:`Gains of 20+ yards: ${pct(u.exp)} of eligible plays versus ${pct(v.exp)} for ${fav}. Explosiveness and success rate belong to the same evidence family.`})}
 const diff=f.features[5]*(underHome?1:-1);const post=f.features[9]*(underHome?-1:1),look=f.features[10]*(underHome?-1:1);
